using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class C02RefineDetailAudit {
 static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit scene required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string props="Assets/Afrer_Seconds/05.Model/Props/B5/";for(int i=1;i<=4;i++)AssetDatabase.ImportAsset(props+"Textures/SC_Display_"+i.ToString("00")+".png",ImportAssetOptions.ForceSynchronousImport);
 var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C02_Security_Art");var infill=room.Find("C02_Equipment_Infill");var origin=room.position;var collisions=new List<object>();var propsBoxes=room.GetComponentsInChildren<BoxCollider>();Physics.SyncTransforms();foreach(var a in infill.GetComponentsInChildren<BoxCollider>())foreach(var b in propsBoxes){if(a==b||b.transform.IsChildOf(infill)&&Array.IndexOf(propsBoxes,a)>Array.IndexOf(propsBoxes,b))continue;Vector3 dir;float depth;if(Physics.ComputePenetration(a,a.transform.position,a.transform.rotation,b,b.transform.position,b.transform.rotation,out dir,out depth)&&depth>.005f)collisions.Add(new{a=a.name,b=b.name,depth});}
 var bounds=infill.GetComponentsInChildren<MeshFilter>().Select(m=>new{m.name,maxRadius=m.sharedMesh.vertices.Max(v=>(m.transform.TransformPoint(v)-origin).magnitude),minHeight=m.sharedMesh.vertices.Min(v=>m.transform.TransformPoint(v).y-origin.y)}).ToArray();
 var paths=new[]{new[]{Vector3.zero,new Vector3(-2.6f,0,3.3f)},new[]{Vector3.zero,new Vector3(-4.9f,0,-.3f)},new[]{Vector3.zero,new Vector3(3.4f,0,-3.3f)},new[]{Vector3.zero,new Vector3(-3.7f,0,-.9f)},new[]{new Vector3(-3.7f,0,-.9f),new Vector3(-4.2f,0,-2.9f)}};int samples=0;var blocked=new List<object>();foreach(var path in paths){int n=Mathf.CeilToInt(Vector3.Distance(path[0],path[1])/.10f);for(int i=0;i<=n;i++){samples++;var p=origin+Vector3.Lerp(path[0],path[1],(float)i/n);var hits=Physics.OverlapCapsule(p+Vector3.up*.37f,p+Vector3.up*1.50f,.28f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(root)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold")).ToArray();if(hits.Length>0)blocked.Add(new{p=V(p),hits=hits.Select(h=>h.name).ToArray()});}}
 var layout=JObject.Parse(File.ReadAllText(repo+"/Docs/도면/Decision/원형공동/facility_layout.json"));var floor=layout["floors"].Single(f=>(string)f["id"]=="B5");var renderers=root.GetComponentsInChildren<Renderer>(true);var map=new List<object>();foreach(var r in floor["rooms"]){string id=(string)r["id"];var found=renderers.FirstOrDefault(v=>v.name.StartsWith("CF_B5_"+id+"_Dome"));map.Add(new{code=id,found=found!=null,centerErrorXZ=found?Vector2.Distance(new Vector2(found.bounds.center.x,found.bounds.center.z),new Vector2((float)r["x"],-(float)r["v"])):-1});}
 var result=new{collisionPairs=collisions,bounds,accessSamples=samples,blocked,map,links=floor["tunnels"].Count(),scene=s.path};File.WriteAllText(repo+"/Docs/검수/2026-11-08_C02_Refine/detail_audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
